          if (visits === 1) frequencyDistribution["1 compra"]++;
          else if (visits >= 2 && visits <= 5) frequencyDistribution["2-5 compras"]++;
          else if (visits >= 6 && visits <= 10) frequencyDistribution["6-10 compras"]++;
