            )
          )
          .groupBy(sql`DATE_TRUNC('day', ${transactions.created_at})`)
          .orderBy(sql`DATE_TRUNC('day', ${transactions.created_at})`);

        // Dados fictícios para a distribuição de cashback por tipo
        const distribution = [
