      const host = req.get('host') || 'valecashback.com';
      const protocol = req.protocol || 'https';
      const referralUrl = `${protocol}://${host}/convite/${userReferralCode}`;

      res.json({
        referralCode: userReferralCode,
        referralUrl,
        referralsCount,
        pendingReferrals,
        activeReferrals,
        totalEarned: totalEarned.toFixed(2),
        commission: (commissionRate * 100).toFixed(1),
        referrals: referrals_list,
        monthlyEarnings: [
          { month: "Jan", value: 0 },
          { month: "Fev", value: 0 },
          { month: "Mar", value: 0 },
          { month: "Abr", value: 0 },
          { month: "Mai", value: 0 },
          { month: "Jun", value: 0 },
          { month: "Jul", value: 0 },
          { month: "Ago", value: 0 },
          { month: "Set", value: 0 },
          { month: "Out", value: 0 },
          { month: "Nov", value: 0 },
          { month: "Dez", value: 0 }
        ]
      });
    } catch (error) {
      console.error("Erro ao buscar referências:", error);

      // Em caso de erro, retornar pelo menos o código de referência básico
      const merchantId = req.user?.id || 0;
