              transactionType: "Sale",
              amount: amount,
              platformFee: amount * parseFloat(platformFee) / 100,
              description: `Taxa de plataforma (${platformFee}%)`
            };
          })
        },
        transactions: {
          recentTransactions,
          feeDistribution
        }
      };

      res.status(200).json(response);
