          })
          .from(transactions)
          .innerJoin(users, eq(transactions.user_id, users.id))
          .where(eq(transactions.merchant_id, merchant.id))
          .groupBy(transactions.user_id, users.name)
          .orderBy(sql`SUM(${transactions.amount})`, "desc")
          .limit(5);

        response = {
