        commission: (commissionRate * 100).toFixed(1),
        referrals: referrals_list,
        monthlyEarnings: [
          { month: "Jan", value: 0 },
          { month: "Fev", value: 0 },
          { month: "Mar", value: 0 },
          { month: "Abr", value: 0 },
          { month: "Mai", value: 0 },
          { month: "Jun", value: 0 },
          { month: "Jul", value: 0 },
          { month: "Ago", value: 0 },
          { month: "Set", value: 0 },
          { month: "Out", value: 0 },
          { month: "Nov", value: 0 },
          { month: "Dez", value: 0 }
        ]
      });
