function Router() {
  // Vamos simplificar completamente a lógica de roteamento para evitar conflitos

  // Rota atual
  const currentPath = window.location.pathname;
  console.log("Rota atual detectada:", currentPath);

  // Renderização direta das páginas de boas-vindas sem redirecionamentos complexos
  if (currentPath === '/welcome-simple') {
