    return <WelcomeNewPage />;
  }

  if (currentPath === '/welcome-static' || currentPath === '/welcome') {
    console.log("Renderizando página static");
    return <WelcomeStaticPage />;
  }

  // Se estamos na raiz, mostre a nova página de boas-vindas aprimorada
