import express, { type Express } from "express";
import fs from "fs";
import path from "path";
import { createServer as createViteServer, createLogger } from "vite";
import { type Server } from "http";
import viteConfig from "../vite.config";
import { nanoid } from "nanoid";

const viteLogger = createLogger();

export function log(message: string, source = "express") {
  const formattedTime = new Date().toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    second: "2-digit",
    hour12: true,
  });

  console.log(`${formattedTime} [${source}] ${message}`);
}

export async function setupVite(app: Express, server: Server) {
  const serverOptions = {
    middlewareMode: true,
    hmr: { server },
    allowedHosts: true,
  };

  const vite = await createViteServer({
    ...viteConfig,
    configFile: false,
    customLogger: {
      ...viteLogger,
      error: (msg, options) => {
        viteLogger.error(msg, options);
        process.exit(1);
      },
    },
    server: serverOptions,
    appType: "custom",
  });

  app.use(vite.middlewares);
  app.use("*", async (req, res, next) => {
    const url = req.originalUrl;

    try {
      const clientTemplate = path.resolve(
        import.meta.dirname,
        "..",
        "client",
        "index.html",
      );

      // always reload the index.html file from disk incase it changes
      let template = await fs.promises.readFile(clientTemplate, "utf-8");
      template = template.replace(
        `src="/src/main.tsx"`,
        `src="/src/main.tsx?v=${nanoid()}"`,
      );
      const page = await vite.transformIndexHtml(url, template);
      res.status(200).set({ "Content-Type": "text/html" }).end(page);
    } catch (e) {
      vite.ssrFixStacktrace(e as Error);
      next(e);
    }
  });
}

export function serveStatic(app: Express) {
  const distPath = path.resolve(import.meta.dirname, "public");

  if (!fs.existsSync(distPath)) {
    throw new Error(
      `Could not find the build directory: ${distPath}, make sure to build the client first`,
    );
  }

  app.use(express.static(distPath));

  // fall through to index.html if the file doesn't exist
  app.use("*", (_req, res) => {
    res.sendFile(path.resolve(distPath, "index.html"));
  });
}

netlify_deploy/shared/schema.ts.content:
import { pgTable, text, serial, integer, numeric, boolean, timestamp, uniqueIndex, foreignKey } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// User types enum
export const UserType = {
  CLIENT: "client",
  MERCHANT: "merchant",
  ADMIN: "admin",
} as const;

export type UserTypeValues = typeof UserType[keyof typeof UserType];

// Transaction status enum
export const TransactionStatus = {
  COMPLETED: "completed",
  PENDING: "pending",
  CANCELLED: "cancelled",
  REFUNDED: "refunded",
} as const;

export type TransactionStatusValues = typeof TransactionStatus[keyof typeof TransactionStatus];

// Payment methods enum
export const PaymentMethod = {
  CASH: "cash",
  CREDIT_CARD: "credit_card",
  DEBIT_CARD: "debit_card",
  CASHBACK: "cashback",
  PIX: "pix",
} as const;

export type PaymentMethodValues = typeof PaymentMethod[keyof typeof PaymentMethod];

// Users table
export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  name: text("name").notNull(),
  username: text("username").unique(),
  email: text("email").notNull().unique(),
  password: text("password").notNull(),
  phone: text("phone"),
  country: text("country"),
  country_code: text("country_code"),
  type: text("type").notNull(),
  status: text("status").notNull().default("active"),
  photo: text("photo"),
  security_question: text("security_question"),
  security_answer: text("security_answer"),
  invitation_code: text("invitation_code"),
  created_at: timestamp("created_at").notNull().defaultNow(),
  last_login: timestamp("last_login"),
});

// Merchants table (extends users)
export const merchants = pgTable("merchants", {
  id: serial("id").primaryKey(),
  user_id: integer("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  store_name: text("store_name").notNull(),
  logo: text("logo"),
  category: text("category").notNull(),
  address: text("address"),
  city: text("city"),
  state: text("state"),
  country: text("country"),
  company_logo: text("company_logo"),
  commission_rate: numeric("commission_rate").notNull().default("2.0"),
  approved: boolean("approved").notNull().default(false),
  created_at: timestamp("created_at").notNull().defaultNow(),
});

// Cashback balances
export const cashbacks = pgTable("cashbacks", {
  id: serial("id").primaryKey(),
  user_id: integer("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  balance: numeric("balance").notNull().default("0.0"),
  total_earned: numeric("total_earned").notNull().default("0.0"),
  updated_at: timestamp("updated_at").notNull().defaultNow(),
});

// Products/Services
export const products = pgTable("products", {
  id: serial("id").primaryKey(),
  merchant_id: integer("merchant_id").notNull().references(() => merchants.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  description: text("description"),
  price: numeric("price").notNull(),
  category: text("category"),
  inventory_count: integer("inventory_count"),
  active: boolean("active").notNull().default(true),
  created_at: timestamp("created_at").notNull().defaultNow(),
});

// Transactions
export const transactions = pgTable("transactions", {
  id: serial("id").primaryKey(),
  user_id: integer("user_id").notNull().references(() => users.id),
  merchant_id: integer("merchant_id").notNull().references(() => merchants.id),
  amount: numeric("amount").notNull(),
  cashback_amount: numeric("cashback_amount").notNull(),
  description: text("description"),
  status: text("status").notNull().default("completed"),
  payment_method: text("payment_method").notNull(),
  created_at: timestamp("created_at").notNull().defaultNow(),
  // Optional fields that might not be in all database instances
  manual_amount: numeric("manual_amount"),
});

// Transaction Items
export const transactionItems = pgTable("transaction_items", {
  id: serial("id").primaryKey(),
  transaction_id: integer("transaction_id").notNull().references(() => transactions.id, { onDelete: "cascade" }),
  product_id: integer("product_id").references(() => products.id),
  product_name: text("product_name").notNull(),
  quantity: integer("quantity").notNull(),
  price: numeric("price").notNull(),
  created_at: timestamp("created_at").notNull().defaultNow(),
});

// Transfers
export const transfers = pgTable("transfers", {
  id: serial("id").primaryKey(),
  from_user_id: integer("from_user_id").notNull().references(() => users.id),
  to_user_id: integer("to_user_id").notNull().references(() => users.id),
  amount: numeric("amount").notNull(),
  description: text("description"),
  status: text("status").notNull().default("completed"),
  created_at: timestamp("created_at").notNull().defaultNow(),
  type: text("type"),
});

// Referrals
export const referrals = pgTable("referrals", {
  id: serial("id").primaryKey(),
  referrer_id: integer("referrer_id").notNull().references(() => users.id),
  referred_id: integer("referred_id").notNull().references(() => users.id),
  bonus: numeric("bonus").notNull(),
  status: text("status").notNull().default("pending"),
  created_at: timestamp("created_at").notNull().defaultNow(),
});

// QR Codes
export const qrCodes = pgTable("qr_codes", {
  id: serial("id").primaryKey(),
  user_id: integer("user_id").notNull().references(() => users.id),
  code: text("code").notNull().unique(),
  amount: numeric("amount").notNull(),
  description: text("description"),
  expires_at: timestamp("expires_at").notNull(),
  used: boolean("used").notNull().default(false),
  created_at: timestamp("created_at").notNull().defaultNow(),
});

// System settings
export const settings = pgTable("settings", {
  id: serial("id").primaryKey(),
  key: text("key").notNull().unique(),
  value: text("value").notNull(),
  updated_at: timestamp("updated_at").notNull().defaultNow(),
});

// Commission settings
export const commissionSettings = pgTable("commission_settings", {
  id: serial("id").primaryKey(),
  platform_fee: numeric("platform_fee").notNull().default("2.0"),
  merchant_commission: numeric("merchant_commission").notNull().default("2.0"),
  client_cashback: numeric("client_cashback").notNull().default("2.0"),
  referral_bonus: numeric("referral_bonus").notNull().default("1.0"),
  min_withdrawal: numeric("min_withdrawal").notNull().default("50.0"),
  max_cashback_bonus: numeric("max_cashback_bonus").notNull().default("10.0"),
  updated_at: timestamp("updated_at").notNull().defaultNow(),
  updated_by: integer("updated_by").references(() => users.id),
});

// Audit logs
export const auditLogs = pgTable("audit_logs", {
  id: serial("id").primaryKey(),
  user_id: integer("user_id").references(() => users.id),
  action: text("action").notNull(),
  details: text("details"),
  ip_address: text("ip_address"),
  created_at: timestamp("created_at").notNull().defaultNow(),
});

// Insert schemas
export const insertUserSchema = createInsertSchema(users)
  .omit({ id: true, created_at: true, last_login: true });

export const insertMerchantSchema = createInsertSchema(merchants)
  .omit({ id: true, created_at: true });

export const insertTransactionSchema = createInsertSchema(transactions)
  .omit({ id: true, created_at: true });

export const insertTransferSchema = createInsertSchema(transfers)
  .omit({ id: true, created_at: true });

export const insertProductSchema = createInsertSchema(products)
  .omit({ id: true, created_at: true });

export const insertQRCodeSchema = createInsertSchema(qrCodes)
  .omit({ id: true, created_at: true, used: true });

export const insertCommissionSettingsSchema = createInsertSchema(commissionSettings)
  .omit({ id: true, updated_at: true });

// Types
export type User = typeof users.$inferSelect;
export type InsertUser = z.infer<typeof insertUserSchema>;

export type Merchant = typeof merchants.$inferSelect;
export type InsertMerchant = z.infer<typeof insertMerchantSchema>;

export type Cashback = typeof cashbacks.$inferSelect;

export type Transaction = typeof transactions.$inferSelect;
export type InsertTransaction = z.infer<typeof insertTransactionSchema>;

export type TransactionItem = typeof transactionItems.$inferSelect;

export type Transfer = typeof transfers.$inferSelect;
export type InsertTransfer = z.infer<typeof insertTransferSchema>;

export type Product = typeof products.$inferSelect;
export type InsertProduct = z.infer<typeof insertProductSchema>;

export type QRCode = typeof qrCodes.$inferSelect;
export type InsertQRCode = z.infer<typeof insertQRCodeSchema>;

export type Setting = typeof settings.$inferSelect;
export type AuditLog = typeof auditLogs.$inferSelect;
export type CommissionSetting = typeof commissionSettings.$inferSelect;
export type InsertCommissionSetting = z.infer<typeof insertCommissionSettingsSchema>;

// Tipos de notificações
export const NotificationType = {
  TRANSACTION: "transaction",
  CASHBACK: "cashback",
  TRANSFER: "transfer",
  REFERRAL: "referral",
  SYSTEM: "system",
  WITHDRAWAL: "withdrawal"
} as const;

export type NotificationTypeValues = typeof NotificationType[keyof typeof NotificationType];

// Status de solicitação de saque
export const WithdrawalStatus = {
  PENDING: "pending",
  COMPLETED: "completed",
  REJECTED: "rejected",
  CANCELLED: "cancelled"
} as const;

export type WithdrawalStatusValues = typeof WithdrawalStatus[keyof typeof WithdrawalStatus];

// Tabela de notificações
export const notifications = pgTable("notifications", {
  id: serial("id").primaryKey(),
  user_id: integer("user_id").notNull().references(() => users.id),
  type: text("type").notNull().$type<NotificationTypeValues>(),
  title: text("title").notNull(),
  message: text("message").notNull(),
  read: boolean("read").default(false).notNull(),
  data: text("data"),
  created_at: timestamp("created_at").defaultNow().notNull()
});

// Schema para inserção de notificações
export const insertNotificationSchema = createInsertSchema(notifications)
  .omit({ id: true, created_at: true });

// Tipo de notificação
export type Notification = typeof notifications.$inferSelect;
export type InsertNotification = z.infer<typeof insertNotificationSchema>;

// Tabela de solicitações de saque
export const withdrawalRequests = pgTable("withdrawal_requests", {
  id: serial("id").primaryKey(),
  user_id: integer("user_id").notNull().references(() => users.id),
  merchant_id: integer("merchant_id").notNull().references(() => merchants.id),
  amount: numeric("amount").notNull(),
  full_name: text("full_name").notNull(),
  store_name: text("store_name").notNull(),
  phone: text("phone").notNull(),
  email: text("email").notNull(),
  bank_name: text("bank_name").notNull(),
  agency: text("agency").notNull(),
  account: text("account").notNull(),
  payment_method: text("payment_method").notNull().default("bank"),  // bank ou zelle
  status: text("status").notNull().default("pending").$type<WithdrawalStatusValues>(),
  notes: text("notes"),
  processed_by: integer("processed_by").references(() => users.id),
  processed_at: timestamp("processed_at"),
  created_at: timestamp("created_at").defaultNow().notNull(),
  updated_at: timestamp("updated_at").defaultNow().notNull()
});

// Schema para inserção de solicitações de saque
export const insertWithdrawalRequestSchema = createInsertSchema(withdrawalRequests)
  .omit({ id: true, status: true, processed_by: true, processed_at: true, created_at: true, updated_at: true });

// Tipo de solicitação de saque
export type WithdrawalRequest = typeof withdrawalRequests.$inferSelect;
export type InsertWithdrawalRequest = z.infer<typeof insertWithdrawalRequestSchema>;

server/helpers/fee-calculator.ts.content:
import { db } from "../db";
import { commissionSettings } from "@shared/schema";

interface FeeCalculation {
  clientCashback: number;
  platformFee: number;
  referralBonus: number;
  merchantReceives: number;
}

/**
 * Calcula todas as taxas baseadas no novo modelo:
 * - Lojista paga 5% para a plataforma
 * - Cliente recebe 2% de cashback
 * - Bônus de indicação de 1%
 * - Lojista não recebe comissão adicional
 */
export async function calculateTransactionFees(amount: number): Promise<FeeCalculation> {
  // Buscar configurações atuais do banco
  const [settings] = await db.select().from(commissionSettings).limit(1);

  // Usar configurações do banco ou valores padrão
  const platformFeeRate = settings ? parseFloat(settings.platform_fee) / 100 : 0.05; // 5%
  const clientCashbackRate = settings ? parseFloat(settings.client_cashback) / 100 : 0.02; // 2%
  const referralBonusRate = settings ? parseFloat(settings.referral_bonus) / 100 : 0.01; // 1%

  // Cálculos baseados no valor da transação
  const platformFee = amount * platformFeeRate; // 5% do valor total pago pela loja
  const clientCashback = amount * clientCashbackRate; // 2% do valor para o cliente
  const referralBonus = amount * referralBonusRate; // 1% para indicações

  // O lojista recebe o valor total menos a taxa da plataforma (5%)
  const merchantReceives = amount - platformFee;

  return {
    clientCashback,
    platformFee,
    referralBonus,
    merchantReceives
  };
}

/**
 * Calcula apenas o cashback para o cliente
 */
export async function calculateClientCashback(amount: number): Promise<number> {
  const [settings] = await db.select().from(commissionSettings).limit(1);
  const clientCashbackRate = settings ? parseFloat(settings.client_cashback) / 100 : 0.02;

  return amount * clientCashbackRate;
}

/**
 * Calcula a taxa da plataforma que o lojista deve pagar
 */
export async function calculatePlatformFee(amount: number): Promise<number> {
  const [settings] = await db.select().from(commissionSettings).limit(1);
  const platformFeeRate = settings ? parseFloat(settings.platform_fee) / 100 : 0.05;

  return amount * platformFeeRate;
}

/**
 * Calcula o valor que o lojista recebe após descontar a taxa da plataforma
 */
export async function calculateMerchantReceives(amount: number): Promise<number> {
  const platformFee = await calculatePlatformFee(amount);
  return amount - platformFee;
}

/**
 * Calcula bônus de indicação
 */
export async function calculateReferralBonus(amount: number): Promise<number> {
  const [settings] = await db.select().from(commissionSettings).limit(1);
  const referralBonusRate = settings ? parseFloat(settings.referral_bonus) / 100 : 0.01;

  return amount * referralBonusRate;
}

