      console.error("Erro crítico na API:", error);
      setLoadingAPI(false);
    }

    // Para usar apenas na primeira visita, descomentar o código abaixo:
    /*
    const hasSeenSplash = localStorage.getItem('has_seen_splash');
    if (hasSeenSplash) {
      setShowSplash(false);
    } else {
      // Marca como visto para sessões futuras
      localStorage.setItem('has_seen_splash', 'true');
    }
    */
  }, []);

  const handleSplashFinish = () => {
    setShowSplash(false);
  };

  useEffect(() => {
    // Adiciona indicador de modo de desenvolvimento no título da página
    if (process.env.NODE_ENV === 'development') {
      document.title = "[DEV] Vale Cashback";
    }
  }, []);

  // Verificar se estamos na raiz ou em página de boas-vindas
  const currentPath = window.location.pathname;
  const hasSeenWelcome = localStorage.getItem('has_seen_welcome');
  const shouldShowWelcome = 
    (currentPath === '/' && !hasSeenWelcome) || 
    currentPath === '/welcome' || 
    currentPath === '/welcome-static' || 
    currentPath === '/welcome-enhanced';

  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider attribute="class" defaultTheme="light">
        <TranslationProvider>
          <AuthProvider>
            <MobileProvider>
              <TooltipProvider>
                <Toaster />
                {showSplash ? (
                  <SplashScreen onFinish={handleSplashFinish} duration={3000} />
                ) : (
                  <div className="min-h-screen">
                    {/* Se estamos na página raiz ou welcome, mostrar diretamente a página de boas-vindas */}
                    {shouldShowWelcome ? (
                      <WelcomeEnhancedPage />
                    ) : (
                      <>
                        {/* Caso contrário, seguir o fluxo normal */}
                        <Router />
                        <ModernPWAInstall />

                        {/* Alerta de falha de conexão caso API não responda */}
                        {loadingAPI && (
                          <div className="fixed bottom-4 right-4 bg-red-600 text-white p-3 rounded-md z-50 shadow-lg animate-pulse max-w-xs">
                            <div className="flex items-center">
                              <AlertTriangle className="h-5 w-5 mr-2" />
                              <p>Verificando conexão com o servidor...</p>
                            </div>
                          </div>
                        )}
                      </>
                    )}
                  </div>
                )}
              </TooltipProvider>
            </MobileProvider>
          </AuthProvider>
        </TranslationProvider>
      </ThemeProvider>
    </QueryClientProvider>
  );
}

export default App;

