      }

      // Determinar datas de início e fim com base no período
      let start_date, end_date;
      const now = new Date();

      switch (period) {
        case "today":
          start_date = new Date(now.setHours(0, 0, 0, 0));
          end_date = new Date(now.setHours(23, 59, 59, 999));
          break;
        case "week":
          start_date = new Date(now);
          start_date.setDate(start_date.getDate() - 7);
          end_date = new Date(now);
          break;
        case "month":
          start_date = new Date(now);
          start_date.setMonth(start_date.getMonth() - 1);
          end_date = new Date(now);
          break;
        case "quarter":
          start_date = new Date(now);
          start_date.setMonth(start_date.getMonth() - 3);
          end_date = new Date(now);
          break;
        case "year":
          start_date = new Date(now);
          start_date.setFullYear(start_date.getFullYear() - 1);
          end_date = new Date(now);
          break;
        case "custom":
          if (startDate && endDate) {
            start_date = new Date(startDate as string);
            end_date = new Date(endDate as string);
          } else {
            start_date = new Date();
            start_date.setMonth(start_date.getMonth() - 1);
            end_date = new Date();
          }
          break;
        default:
          start_date = new Date();
          start_date.setMonth(start_date.getMonth() - 1);
          end_date = new Date();
          break;
      }

