          created_at: new Date().toISOString(),
          description: "Compra de produtos"
        },
        {
          id: 2,
          userName: "João Santos",
          amount: 150.25,
          cashback_amount: 3.00,
          payment_method: "PIX",
          status: "completed",
          created_at: new Date().toISOString(),
          description: "Serviços prestados"
        },
        {
          id: 3,
          userName: "Ana Oliveira",
          amount: 320.00,
          cashback_amount: 6.40,
          payment_method: "CASH",
          status: "pending",
