      console.log("🔄 Carregando TODAS as transações reais do banco...");

      const { limit = "100" } = req.query;

      // SQL direto para carregar transações reais com nomes completos
      const query = `
        SELECT 
          t.id,
          t.created_at,
          t.amount,
          t.status,
          COALESCE(m.company_name, u1.name, 'Lojista') as merchant_name,
