      const withdrawalTotal = Number(withdrawalTotalResult.rows[0]?.total || 0);

      const fees = [
        {
          type: "Taxa de Transação",
          amount: transactionTotal * 0.025,
          percentage: 2.5,
          description: "Taxa cobrada por transação processada",
          period: "Total"
        },
        {
          type: "Taxa de Saque", 
          amount: withdrawalTotal * 0.02,
