  // API para obter indicações do usuário
  app.get("/api/referrals", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = req.user?.id;
      if (!userId) {
        return res.status(401).json({ message: "Usuário não autenticado" });
      }

      const userReferrals = [
        {
          id: 1,
          referredUser: {
            firstName: "João",
