          }
        ]
      }
    ];

    // Registrar acesso ao suporte no log de auditoria
    await db.insert(auditLogs).values({
      action: "support_accessed",
      entity_type: "support",
      entity_id: 0,
      user_id: req.user.id,
      details: JSON.stringify({
        timestamp: new Date()
      }),
