        cashbackBalance,
        referralBalance,
        transactionsCount,
        recentTransactions,
        monthStats: {
          earned: safeMonthlyEarned,
          transferred: safeMonthlyTransferred,
          received: safeMonthlyReceived
        },
        balanceHistory
      };

