        const [updatedSettings] = await db.update(brandSettings)
          .set({
            ...updateData,
            updated_at: new Date(),
            updated_by: req.user?.id
          })
          .where(eq(brandSettings.id, id))
          .returning();

        if (!updatedSettings) {
          return res.status(404).json({ message: 'Configurações não encontradas' });
        }

