          previousStatus: transfer.status,
          newStatus: status,
          notes
        }),
        created_at: new Date()
      });

      res.json({ 
        success: true, 
        message: `Transferência ${
          status === 'approved' ? 'aprovada' : 
          status === 'rejected' ? 'rejeitada' : 
          status === 'processing' ? 'em processamento' :
