          FROM referrals r
          JOIN users u ON r.referred_id = u.id
          LEFT JOIN merchants m ON u.type = 'merchant' AND m.user_id = u.id
          WHERE r.referrer_id = ${merchantId}
          ORDER BY r.id, r.created_at DESC
