              }
              setReferralCode(data.invitationCode);
            }
            setLoading(false);
          })
          .catch(err => {
            console.error("Error fetching invitation code:", err);
            setLoading(false);
          });
        return;
      }
    }

    // Se não detectou nenhum código, define um padrão
    setReferralType("client"); // Define cliente como tipo padrão
    setLoading(false);
  }, [location, loading]);

