    // Verificar credenciais
    const user = testUsers[username];
    if (!user || user.password !== password) {
      return res.status(401).json({ message: 'Credenciais inválidas' });
    }

    // Login bem-sucedido
    req.session.userId = user.id;
    req.session.userType = user.type;

