        usersSql += userIdsList.join(',') + ')';
      }

      const usersResult = await db.execute(sql`${sql.raw(usersSql)}`);

      // Criar mapa para fácil acesso
      const usersMap = new Map(usersResult.rows.map(u => [u.id, u.name]));

