      }

      if (!photo) {
        return res.status(400).json({ message: "Nenhuma imagem fornecida" });
      }

      // Validar a imagem (base64)
      if (!photo.startsWith('data:image/')) {
        return res.status(400).json({ message: "Formato de imagem inválido" });
      }

      // Atualizar a foto do perfil
