            await fs.copy(faviconSource, path.join(publicDir, `favicon${extension}`));

            // Se for SVG, atualizar favicon.svg
            if (extension === '.svg') {
              await fs.copy(faviconSource, path.join(publicDir, 'favicon.svg'));
