  app.post("/api/register/merchant", async (req, res) => {
    try {
      const { name, email, password, phone, storeName, storeType, referralCode, referralInfo } = req.body;

      // Verificar se o email já existe
      const existingUser = await db
        .select()
        .from(users)
        .where(eq(users.email, email))
        .limit(1);

      if (existingUser.length) {
        return res.status(400).json({ message: "Email já cadastrado" });
      }

      // Gerar código de lojista baseado no próximo ID
      const lastUserId = await db
        .select({ maxId: sql`MAX(${users.id})` })
        .from(users);

      const nextId = (lastUserId[0]?.maxId || 0) + 1;
      const username = `${nextId}_Lojista`;

      // Cadastrar novo usuário
      const [newUser] = await db
        .insert(users)
        .values({
          name,
          email,
          username,
          password, // Em produção, usaríamos hashPassword(password)
          phone,
          type: "merchant",
          status: "active", // Lojistas são aprovados automaticamente
          invitation_code: `LJ${nextId.toString().padStart(4, '0')}`, // Gerar código de convite para o novo lojista
          created_at: new Date()
        })
        .returning();

      // Registrar informações da loja
      await db
        .insert(merchants)
        .values({
          user_id: newUser.id,
          store_name: storeName,
          category: storeType || "Geral",
          approved: true,
          created_at: new Date()
        });

      // Processar código de referência, se fornecido (via URL ou via formulário)
      let refCode = null;
      // Prioridade 1: Verificar referralInfo que vem de inviteData
      if (referralInfo && referralInfo.referralCode) {
        refCode = referralInfo.referralCode;
        console.log("Usando código de referralInfo:", refCode);
      } 
      // Prioridade 2: Verificar referralCode do formulário
      else if (referralCode) {
        refCode = referralCode;
        console.log("Usando código de referralCode:", refCode);
      }
      // Prioridade 3: Tentar extrair da URL de referrer (caso o usuário entre direto pelo link)
      else if (req.headers.referer) {
        const refererUrl = new URL(req.headers.referer);
        const pathParts = refererUrl.pathname.split('/').filter(part => part.trim() !== '');

        console.log("Analisando URL de referência:", refererUrl.pathname);

        // Verificar se há algum código de indicação nos segmentos da URL
        for (const part of pathParts) {
          if (part.match(/^CL[0-9]+$/i) || part.match(/^LJ[0-9]+$/i)) {
            refCode = part;
            console.log("Código extraído da URL de referência:", refCode);
            break;
          }
        }
      }

      if (refCode) {
        console.log(`Processando indicação de lojista com código: ${refCode}`);

        // Buscar usuário que fez a indicação pelo código
        const referrerQuery = await db
          .select()
          .from(users)
          .where(eq(users.invitation_code, refCode))
          .limit(1);

        if (referrerQuery.length > 0) {
          const referrer = referrerQuery[0];
          console.log(`Lojista ${newUser.id} registrado com referência de ${referrer.id} (${referrer.name})`);

          // Verificar se já existe um registro para esta referência
          const existingReferral = await db
            .select()
            .from(referrals)
            .where(and(
              eq(referrals.referrer_id, referrer.id),
              eq(referrals.referred_id, newUser.id)
            ))
            .limit(1);

          if (existingReferral.length === 0) {
            // Buscar a taxa de referral_bonus configurada no sistema
            let referralBonus = "0.01"; // Valor padrão de 1%
            try {
              const settingsResult = await db
                .select()
                .from(commissionSettings)
                .limit(1);

              if (settingsResult.length > 0) {
                referralBonus = settingsResult[0].referral_bonus.toString();
              }
            } catch (error) {
              console.error("Erro ao buscar taxa de referral_bonus:", error);
              // Mantém o valor padrão em caso de erro
            }

            // Converter o valor do bônus para número para operações seguras
            let bonusValue = 0.01;
            try {
              bonusValue = parseFloat(referralBonus);
              // Formatar com 2 casas decimais para consistência
              bonusValue = parseFloat(bonusValue.toFixed(2));
            } catch (error) {
              console.error("Erro ao converter valor do bônus:", error);
              bonusValue = 0.01; // Valor padrão seguro
            }

            // Registrar a referência com o bônus apenas se não existir
            try {
              await db.insert(referrals).values({
                referrer_id: referrer.id,
                referred_id: newUser.id,
                bonus: bonusValue.toString(), // Taxa de bônus configurada no sistema
                status: "active",
                created_at: new Date()
              });

              console.log(`✅ Referência registrada com sucesso para o lojista ${newUser.id} com bônus de ${bonusValue}`);
            } catch (refError) {
              console.error(`❌ Erro ao registrar referência: ${refError.message}`);
              // Continuamos para tentar atualizar o cashback mesmo se o registro falhar
            }

            // Aplicar o bônus ao saldo de cashback do referenciador
            try {
              // Buscar cashback atual do referenciador
              const referrerCashback = await db
                .select()
                .from(cashbacks)
                .where(eq(cashbacks.user_id, referrer.id));

              if (referrerCashback.length > 0) {
                // Atualizar cashback existente
                let currentBalance = 0;
                let currentTotalEarned = 0;

                try {
                  currentBalance = parseFloat(referrerCashback[0].balance?.toString() || "0");
                  currentTotalEarned = parseFloat(referrerCashback[0].total_earned?.toString() || "0");
                } catch (parseError) {
                  console.error("Erro ao converter valores de cashback:", parseError);
                }

                // Adicionar bônus ao saldo atual
                const newBalance = (currentBalance + bonusValue).toFixed(2);
                const newTotalEarned = (currentTotalEarned + bonusValue).toFixed(2);

                await db
                  .update(cashbacks)
                  .set({
                    balance: newBalance,
                    total_earned: newTotalEarned,
                    updated_at: new Date()
                  })
                  .where(eq(cashbacks.user_id, referrer.id));

                console.log(`Cashback do referenciador ${referrer.id} atualizado: saldo ${currentBalance} -> ${newBalance}`);
              } else {
                // Criar novo registro de cashback
                await db.insert(cashbacks).values({
                  user_id: referrer.id,
                  balance: bonusValue.toString(),
                  total_earned: bonusValue.toString(),
                  updated_at: new Date()
                });

                console.log(`Novo cashback criado para referenciador ${referrer.id} com bônus inicial de ${bonusValue}`);
              }
            } catch (cashbackError) {
              console.error("Erro ao atualizar cashback do referenciador:", cashbackError);
            }
          } else {
            console.log(`Referência já existente para o lojista ${newUser.id}, ignorando duplicação`);
          }
        } else {
          console.log(`Código de indicação ${refCode} não encontrado no banco de dados`);
        }
      }

      res.status(201).json({
        id: newUser.id,
        name: newUser.name,
        email: newUser.email,
        type: newUser.type,
        message: "Cadastro realizado com sucesso! Sua loja foi aprovada automaticamente."
      });
    } catch (error) {
      console.error("Erro ao cadastrar lojista:", error);
      res.status(500).json({ message: "Erro ao processar o cadastro" });
    }
  });

  // Rotas de notificações
  app.get("/api/notifications", isAuthenticated, async (req, res) => {
    try {
      const userId = req.user!.id;

      // Buscar notificações do usuário
      const userNotifications = await db
        .select()
        .from(notifications)
        .where(eq(notifications.user_id, userId))
        .orderBy(desc(notifications.created_at))
        .limit(50);

      // Contar notificações não lidas
      const [result] = await db
        .select({ count: count() })
        .from(notifications)
        .where(and(
          eq(notifications.user_id, userId),
          eq(notifications.read, false)
        ));

      const unreadCount = result ? Number(result.count) : 0;

      res.json({
        notifications: userNotifications,
        unreadCount
      });
    } catch (error) {
      console.error("Erro ao buscar notificações:", error);
      res.status(500).json({ message: "Erro ao buscar notificações" });
    }
  });

  // Marcar notificação como lida
  app.patch("/api/notifications/:id/read", isAuthenticated, async (req, res) => {
    try {
      const userId = req.user!.id;
      const notificationId = parseInt(req.params.id);

      if (isNaN(notificationId)) {
        return res.status(400).json({ message: "ID de notificação inválido" });
      }

      // Verificar se a notificação pertence ao usuário
      const [notification] = await db
        .select()
        .from(notifications)
        .where(and(
          eq(notifications.id, notificationId),
          eq(notifications.user_id, userId)
        ));

      if (!notification) {
        return res.status(404).json({ message: "Notificação não encontrada" });
      }

      // Marcar como lida
      await db
        .update(notifications)
        .set({ read: true })
        .where(eq(notifications.id, notificationId));

      res.json({ success: true });
    } catch (error) {
      console.error("Erro ao marcar notificação como lida:", error);
      res.status(500).json({ message: "Erro ao marcar notificação como lida" });
    }
  });

  // Marcar todas as notificações como lidas
  app.patch("/api/notifications/mark-all-read", isAuthenticated, async (req, res) => {
    try {
      const userId = req.user!.id;

      // Marcar todas as notificações do usuário como lidas
      await db
        .update(notifications)
        .set({ read: true })
        .where(eq(notifications.user_id, userId));

      res.json({ success: true });
    } catch (error) {
      console.error("Erro ao marcar todas notificações como lidas:", error);
      res.status(500).json({ message: "Erro ao marcar todas notificações como lidas" });
    }
  });

  // Excluir notificação
  app.delete("/api/notifications/:id", isAuthenticated, async (req, res) => {
    try {
      const userId = req.user!.id;
      const notificationId = parseInt(req.params.id);

      if (isNaN(notificationId)) {
        return res.status(400).json({ message: "ID de notificação inválido" });
      }

      // Verificar se a notificação pertence ao usuário
      const [notification] = await db
        .select()
        .from(notifications)
        .where(and(
          eq(notifications.id, notificationId),
          eq(notifications.user_id, userId)
        ));

      if (!notification) {
        return res.status(404).json({ message: "Notificação não encontrada" });
      }

      // Excluir a notificação
      await db
        .delete(notifications)
        .where(eq(notifications.id, notificationId));

      res.json({ success: true });
    } catch (error) {
      console.error("Erro ao excluir notificação:", error);
      res.status(500).json({ message: "Erro ao excluir notificação" });
    }
  });

  const httpServer = createServer(app);

  return httpServer;
}

import { Request, Response, Express } from "express";
import { db } from "./db";
import { eq, desc, and, sql } from "drizzle-orm";
import { isUserType } from "./routes";
import { 
  withdrawalRequests, 
  WithdrawalStatus,
  WithdrawalStatusValues,
  cashbacks, 
  users,
  merchants
} from "@shared/schema";
import { createWithdrawalRequestNotification, createAdminWithdrawalNotification } from "./helpers/notification";

// Validação dos dados de solicitação de saque
function validateWithdrawalData(data: any) {
  const errors = [];

  // Validar valor do saque
  if (!data.amount || isNaN(parseFloat(data.amount)) || parseFloat(data.amount) <= 0) {
    errors.push("Valor do saque inválido");
  }

  // Valor mínimo de saque
  if (parseFloat(data.amount) < 20) {
    errors.push("O valor mínimo para saque é de $20,00");
  }

  // Validar campos obrigatórios
  if (!data.full_name) errors.push("Nome completo é obrigatório");
  if (!data.store_name) errors.push("Nome da loja é obrigatório");
  if (!data.phone) errors.push("Telefone é obrigatório");
  if (!data.email) errors.push("Email é obrigatório");
  if (!data.bank_name) errors.push("Nome do banco é obrigatório");
  if (!data.agency) errors.push("Agência é obrigatória");
  if (!data.account) errors.push("Conta é obrigatória");
  if (!data.payment_method) errors.push("Método de pagamento é obrigatório");

  return errors;
}

export function addWithdrawalRoutes(app: Express) {
  // Rota para obter dados da carteira do lojista (saldo atual, pendente e disponível)
  app.get("/api/merchant/wallet", isUserType("merchant"), async (req: Request, res: Response) => {
    try {
      const userId = req.user!.id;

      // Verificar se o usuário é um lojista
      const merchantResult = await db.select().from(merchants).where(eq(merchants.user_id, userId)).limit(1);
      if (merchantResult.length === 0) {
        return res.status(403).json({ 
          success: false, 
          message: "Acesso restrito a lojistas" 
        });
      }

      const merchant = merchantResult[0];

      // Buscar o saldo atual do lojista na tabela de cashbacks
      const cashbackResult = await db
        .select()
        .from(cashbacks)
        .where(eq(cashbacks.user_id, userId));

      // Calcular saldo atual (usando o valor da tabela de cashbacks)
      let currentBalance = 0;
      if (cashbackResult.length > 0) {
        currentBalance = parseFloat(cashbackResult[0].balance);
      }

      // Buscar saques pendentes (apenas para exibição, pois o valor já foi descontado)
      const pendingWithdrawals = await db
        .select({
          total: sql`SUM(CAST(amount as DECIMAL(10,2)))`.as("total"),
          count: sql`COUNT(*)`.as("count")
        })
        .from(withdrawalRequests)
        .where(
          and(
            eq(withdrawalRequests.user_id, userId),
            eq(withdrawalRequests.status, "pending")
          )
        );

      // Calcular valores
      const pendingAmount = parseFloat(pendingWithdrawals[0]?.total?.toString() || "0");
      const pendingCount = parseInt(pendingWithdrawals[0]?.count?.toString() || "0");

      // Como o valor já foi descontado do saldo ao criar a solicitação,
      // o saldo disponível é igual ao saldo atual
      const availableBalance = currentBalance;

      // Retornar dados da carteira
      res.json({
        success: true,
        walletData: {
          currentBalance,
          pendingAmount,
          pendingCount,
          availableBalance
        }
      });
    } catch (error) {
      console.error("Erro ao buscar dados da carteira:", error);
      res.status(500).json({ 
        success: false, 
        message: "Erro ao buscar dados da carteira" 
      });
    }
  });

  // Rota para lojista criar uma solicitação de saque
  app.post("/api/merchant/withdrawal-requests", isUserType("merchant"), async (req: Request, res: Response) => {
    try {
      const userId = req.user!.id;
      const data = req.body;

      // Validar dados da solicitação
      const validationErrors = validateWithdrawalData(data);
      if (validationErrors.length > 0) {
        return res.status(400).json({ 
          success: false, 
          message: "Dados inválidos", 
          errors: validationErrors 
        });
      }

      // Verificar saldo do lojista
      const [merchantBalance] = await db
        .select()
        .from(cashbacks)
        .where(eq(cashbacks.user_id, userId));

      if (!merchantBalance) {
        return res.status(400).json({ 
          success: false, 
          message: "Saldo não encontrado" 
        });
      }

      const amount = parseFloat(data.amount);
      const currentBalance = parseFloat(merchantBalance.balance);

      // Obter a taxa de saque das configurações do sistema
      let withdrawalFeePercentage = 5.0; // Valor padrão de 5% caso não seja encontrado nas configurações

      try {
        // Importar a tabela de configurações de comissões
        const { commissionSettings } = await import("@shared/schema");

        // Buscar as configurações de taxas mais recentes
        const allCommissionSettings = await db
          .select()
          .from(commissionSettings)
          .limit(10);

        // Ordenar manualmente do lado da aplicação para pegar a mais recente
        if (allCommissionSettings.length > 0) {
          allCommissionSettings.sort((a, b) => {
            if (!a.updated_at || !b.updated_at) return 0;
            return new Date(b.updated_at).getTime() - new Date(a.updated_at).getTime();
          });

          const latestSettings = allCommissionSettings[0];

          try {
            // Tentar acessar a propriedade withdrawal_fee de forma segura
            const withdrawalFee = latestSettings.withdrawal_fee;
            if (withdrawalFee) {
              withdrawalFeePercentage = parseFloat(withdrawalFee);
              console.log(`Taxa de saque definida para ${withdrawalFeePercentage}% a partir das configurações`);
            } else {
              // Se withdrawal_fee não existir ou for nulo, usamos 5% como padrão
              withdrawalFeePercentage = 5.0;
              console.log(`Usando taxa de saque padrão de ${withdrawalFeePercentage}%`);
            }
          } catch (accessError) {
            // Se ocorrer erro ao acessar a propriedade (ex: a coluna não existe ainda)
            withdrawalFeePercentage = 5.0;
            console.log(`Usando taxa de saque padrão de ${withdrawalFeePercentage}% (erro ao acessar propriedade)`);
          }
        }
      } catch (error) {
        console.warn("Erro ao buscar configurações de taxas:", error);
        // Em caso de erro, continua com a taxa padrão
      }

      // Calcular o valor líquido e o valor da taxa
      const feeAmount = amount * (withdrawalFeePercentage / 100);
      const netAmount = amount - feeAmount;

      // Como o valor já é automaticamente descontado do saldo,
      // verificamos apenas se o saldo atual é suficiente para o saque
      if (amount > currentBalance) {
        return res.status(400).json({ 
          success: false, 
          message: `Saldo insuficiente para este saque. Saldo disponível: $${currentBalance.toFixed(2)}` 
        });
      }

      // Obter dados do lojista
      const [merchant] = await db
        .select()
        .from(merchants)
        .where(eq(merchants.user_id, userId));

      if (!merchant) {
        return res.status(400).json({ 
          success: false, 
          message: "Dados do lojista não encontrados" 
        });
      }

      // Criar a solicitação de saque
      const [withdrawalRequest] = await db
        .insert(withdrawalRequests)
        .values({
          user_id: userId,
          merchant_id: merchant.id,
          amount: amount.toFixed(2),
          fee_amount: feeAmount.toFixed(2),
          net_amount: netAmount.toFixed(2),
          fee_percentage: withdrawalFeePercentage.toFixed(1),
          status: WithdrawalStatus.PENDING,
          payment_method: data.payment_method,
          full_name: data.full_name,
          store_name: data.store_name,
          phone: data.phone,
          email: data.email,
          bank_name: data.bank_name,
          agency: data.agency,
          account: data.account,
          created_at: new Date(),
          processed_at: null,
          notes: null
        })
        .returning();

      // Descontar o valor imediatamente da carteira do lojista (aprovisionamento)
      await db
        .update(cashbacks)
        .set({
          balance: sql`balance - ${amount.toFixed(2)}`,
          updated_at: new Date()
        })
        .where(eq(cashbacks.user_id, userId));

      // Criar notificação para o lojista
      await createWithdrawalRequestNotification(
        userId,
        withdrawalRequest.id,
        WithdrawalStatus.PENDING,
        amount.toFixed(2)
      );

      // Criar notificação para administradores
      await createAdminWithdrawalNotification(
        merchant.id,
        merchant.store_name,
        withdrawalRequest.id,
        amount.toFixed(2)
      );

      // Retornar a solicitação criada
      res.status(201).json({
        success: true,
        withdrawalRequest
      });
    } catch (error) {
      console.error("Erro ao criar solicitação de saque:", error);
      res.status(500).json({ 
        success: false, 
        message: "Erro ao processar solicitação de saque"
      });
    }
  });

  // Rota para lojista visualizar suas solicitações de saque
  app.get("/api/merchant/withdrawal-requests", isUserType("merchant"), async (req: Request, res: Response) => {
    try {
      const userId = req.user!.id;

      const withdrawals = await db
        .select()
        .from(withdrawalRequests)
        .where(eq(withdrawalRequests.user_id, userId))
        .orderBy(desc(withdrawalRequests.created_at));

      res.json({
        success: true,
        withdrawals
      });
    } catch (error) {
      console.error("Erro ao buscar solicitações de saque:", error);
      res.status(500).json({ 
        success: false, 
        message: "Erro ao buscar solicitações de saque"
      });
    }
  });

  // Rota para lojista cancelar uma solicitação de saque pendente
  app.delete("/api/merchant/withdrawal-requests/:id", isUserType("merchant"), async (req: Request, res: Response) => {
    try {
      const userId = req.user!.id;
      const requestId = parseInt(req.params.id);

      // Verificar se a solicitação existe e pertence ao lojista
      const [withdrawalRequest] = await db
        .select()
        .from(withdrawalRequests)
        .where(
          and(
            eq(withdrawalRequests.id, requestId),
            eq(withdrawalRequests.user_id, userId)
          )
        );

      if (!withdrawalRequest) {
        return res.status(404).json({ 
          success: false, 
          message: "Solicitação de saque não encontrada" 
        });
      }

      // Verificar se a solicitação ainda está pendente
      if (withdrawalRequest.status !== WithdrawalStatus.PENDING) {
        return res.status(400).json({ 
          success: false, 
          message: "Apenas solicitações pendentes podem ser canceladas" 
        });
      }

      // Atualizar o status da solicitação para cancelado
      const [updatedRequest] = await db
        .update(withdrawalRequests)
        .set({
          status: WithdrawalStatus.CANCELLED,
          processed_at: new Date(),
          updated_at: new Date(),
          notes: "Cancelado pelo lojista"
        })
        .where(eq(withdrawalRequests.id, requestId))
        .returning();

      // Devolver o valor para a carteira do lojista
      await db
        .update(cashbacks)
        .set({
          balance: sql`balance + ${withdrawalRequest.amount}`,
          updated_at: new Date()
        })
        .where(eq(cashbacks.user_id, userId));

      // Notificar o lojista
      await createWithdrawalRequestNotification(
        userId,
        withdrawalRequest.id,
        WithdrawalStatus.CANCELLED,
        withdrawalRequest.amount
      );

      res.json({
        success: true,
        message: "Solicitação de saque cancelada com sucesso",
        withdrawalRequest: updatedRequest
      });
    } catch (error) {
      console.error("Erro ao cancelar solicitação de saque:", error);
      res.status(500).json({ 
        success: false, 
        message: "Erro ao cancelar solicitação de saque"
      });
    }
  });

  // Rota para administrador visualizar todas as solicitações de saque
  app.get("/api/admin/withdrawal-requests", isUserType("admin"), async (req: Request, res: Response) => {
    try {
      const statusFilter = req.query.status as WithdrawalStatusValues | undefined;

      // Usar SQL diretamente para evitar problemas com o typesystem do Drizzle
      let query = `
        SELECT 
          wr.*, 
          m.store_name as merchant_name,
          u.username,
          u.name as user_name,
          u.email as user_email,
          u.phone as user_phone
        FROM 
          withdrawal_requests wr
        LEFT JOIN 
          users u ON wr.user_id = u.id
        LEFT JOIN 
          merchants m ON u.id = m.user_id
      `;

      // Adicionar filtro se necessário
      if (statusFilter) {
        query += ` WHERE wr.status = $1`;
      }

      // Adicionar ordenação
      query += ` ORDER BY wr.created_at DESC`;

      // Executar consulta com parâmetros apropriados
      const { rows: withdrawals } = statusFilter
        ? await db.execute(sql.raw(query, [statusFilter]))
        : await db.execute(sql.raw(query));

      res.json({
        success: true,
        withdrawals
      });
    } catch (error) {
      console.error("Erro ao buscar solicitações de saque:", error);
      res.status(500).json({ 
        success: false, 
        message: "Erro ao buscar solicitações de saque"
      });
    }
  });

  // Rota para administrador processar uma solicitação de saque (aprovar ou rejeitar)
  app.patch("/api/admin/withdrawal-requests/:id", isUserType("admin"), async (req: Request, res: Response) => {
    try {
      const requestId = parseInt(req.params.id);
      const { status, admin_notes } = req.body;

      // Validar status
      if (status !== WithdrawalStatus.COMPLETED && status !== WithdrawalStatus.REJECTED) {
        return res.status(400).json({ 
          success: false, 
          message: "Status inválido" 
        });
      }

      // Verificar se a solicitação existe
      const [existingRequest] = await db
        .select()
        .from(withdrawalRequests)
        .where(eq(withdrawalRequests.id, requestId));

      if (!existingRequest) {
        return res.status(404).json({ 
          success: false, 
          message: "Solicitação de saque não encontrada" 
        });
      }

      // Verificar se a solicitação já foi processada
      if (existingRequest.status !== WithdrawalStatus.PENDING) {
        return res.status(400).json({ 
          success: false, 
          message: "Esta solicitação já foi processada" 
        });
      }

      // Atualizar a solicitação
      const [updatedRequest] = await db
        .update(withdrawalRequests)
        .set({
          status,
          notes: admin_notes || null,
          processed_by: req.user?.id || null,
          processed_at: new Date(),
          updated_at: new Date()
        })
        .where(eq(withdrawalRequests.id, requestId))
        .returning();

      // O valor já foi deduzido na criação da solicitação
      // Se o admin rejeitar, devolver o valor para a carteira do lojista
      if (status === WithdrawalStatus.REJECTED) {
        await db
          .update(cashbacks)
          .set({
            balance: sql`balance + ${existingRequest.amount}`,
            updated_at: new Date()
          })
          .where(eq(cashbacks.user_id, existingRequest.user_id));
      }

      // Enviar notificação para o lojista
      await createWithdrawalRequestNotification(
        existingRequest.user_id,
        existingRequest.id,
        status,
        existingRequest.amount
      );

      res.json({
        success: true,
        withdrawalRequest: updatedRequest
      });
    } catch (error) {
      console.error("Erro ao processar solicitação de saque:", error);
      res.status(500).json({ 
        success: false, 
        message: "Erro ao processar solicitação de saque"
      });
    }
  });
}

import { users, type User, type InsertUser } from "@shared/schema";
import { db } from "./db";
