import passport from "passport";
import { Strategy as LocalStrategy } from "passport-local";
import { Express } from "express";
import session from "express-session";
import { scrypt, randomBytes, timingSafeEqual } from "crypto";
import { promisify } from "util";
import { storage } from "./storage";
import { User, users, auditLogs } from "@shared/schema";
import { db } from "./db";
import { eq } from "drizzle-orm";

declare global {
  namespace Express {
    // Define User interface para o passport
    interface User {
      id: number;
      name: string;
      username: string | null;
      email: string;
      password: string;
      phone: string | null;
      country: string | null;
      country_code: string | null;
      type: string;
      status: string;
      photo: string | null;
      security_question: string | null;
      security_answer: string | null;
      created_at: Date;
      last_login: Date | null;
      invitation_code: string | null;
    }
  }
}

const scryptAsync = promisify(scrypt);

async function hashPassword(password: string) {
  const salt = randomBytes(16).toString("hex");
  const buf = (await scryptAsync(password, salt, 64)) as Buffer;
  return `${buf.toString("hex")}.${salt}`;
}

async function comparePasswords(supplied: string, stored: string) {
  const [hashed, salt] = stored.split(".");
  const hashedBuf = Buffer.from(hashed, "hex");
  const suppliedBuf = (await scryptAsync(supplied, salt, 64)) as Buffer;
  return timingSafeEqual(hashedBuf, suppliedBuf);
}

export function setupAuth(app: Express) {
  const sessionSettings: session.SessionOptions = {
    secret: process.env.SESSION_SECRET || "vale-cashback-secret-key",
    resave: true, // Alterado para true para manter a sessão ativa
    saveUninitialized: false,
    store: storage.sessionStore,
    cookie: {
      maxAge: 1000 * 60 * 60 * 24 * 30, // 30 dias
      sameSite: 'lax',
      secure: process.env.NODE_ENV === 'production',
      httpOnly: true,
    }
  };

  app.set("trust proxy", 1);
  app.use(session(sessionSettings));
  app.use(passport.initialize());
  app.use(passport.session());

  passport.use(
    new LocalStrategy(
      {
        usernameField: 'email',
        passwordField: 'password'
      },
      async (email, password, done) => {
        try {
          const user = await storage.getUserByUsername(email);
          if (!user) {
            return done(null, false, { message: 'Credenciais inválidas' });
          }

          // Em uma aplicação real, usaríamos comparePasswords aqui
          // Por enquanto, estamos comparando diretamente
          if (user.password !== password) {
            return done(null, false, { message: 'Credenciais inválidas' });
          }

          return done(null, user);
        } catch (error) {
          return done(error);
        }
      }
    )
  );

  passport.serializeUser((user, done) => {
    done(null, user.id);
  });

  passport.deserializeUser(async (id: number, done) => {
    try {
      const user = await storage.getUser(id);
      done(null, user);
    } catch (error) {
      done(error);
    }
  });

  app.post("/api/auth/register", async (req, res, next) => {
    try {
      const userData = req.body;

      // Verificar se o email já existe
      const existingUser = await storage.getUserByUsername(userData.email);
      if (existingUser) {
        return res.status(400).json({ message: "Este email já está em uso" });
      }

      // Em produção, devemos hashear a senha
      // userData.password = await hashPassword(userData.password);

      // Criar o usuário
      const user = await storage.createUser(userData);

      // Retorna os dados do usuário (exceto a senha)
      const { password: _, ...userWithoutPassword } = user;

      req.login(user, (err) => {
        if (err) return next(err);
        return res.status(201).json(userWithoutPassword);
      });
    } catch (error: any) {
      console.error("Erro no registro:", error);
      res.status(500).json({ message: error.message || "Erro interno do servidor" });
    }
  });

  app.post("/api/auth/login", (req, res, next) => {
    const { type } = req.body;

    passport.authenticate("local", (err: any, user: any, info: any) => {
      if (err) {
        return next(err);
      }

      if (!user) {
        return res.status(401).json({ message: info?.message || "Credenciais inválidas" });
      }

      // Verificar o tipo de usuário
      if (user.type !== type) {
        return res.status(401).json({ 
          message: "Tipo de usuário incorreto. Por favor, selecione o tipo correto." 
        });
      }

      req.login(user, (loginErr) => {
        if (loginErr) {
          return next(loginErr);
        }

        // Não enviar a senha para o cliente
        const { password: _, ...userWithoutPassword } = user;
        return res.status(200).json(userWithoutPassword);
      });
    })(req, res, next);
  });

  app.post("/api/auth/logout", (req, res, next) => {
    req.logout((err) => {
      if (err) return next(err);
      res.status(200).json({ message: "Logout realizado com sucesso" });
    });
  });

  app.get("/api/auth/me", (req, res) => {
    console.log("Verificando autenticação do usuário:", {
      isAuthenticated: req.isAuthenticated(),
      sessionID: req.sessionID
    });

    if (!req.isAuthenticated()) {
      return res.status(401).json({ message: "Usuário não autenticado" });
    }

    // Não enviar a senha para o cliente
    const { password: _, ...userWithoutPassword } = req.user as User;
    res.json(userWithoutPassword);
  });

  // Rota para recuperação de senha
  app.post("/api/auth/forgot-password", async (req, res) => {
    try {
      const { email, method, securityQuestion, securityAnswer } = req.body;

      // Verificar se o usuário existe
      const user = await db
        .select()
        .from(users)
        .where(eq(users.email, email))
        .limit(1);

      if (!user.length) {
        return res.status(404).json({ message: "Usuário não encontrado" });
      }

      if (method === "security-question") {
        // Em uma implementação real, verificaríamos a resposta da pergunta de segurança
        // contra o valor armazenado no banco de dados

        // Gerar senha temporária
        const tempPassword = randomBytes(4).toString("hex");
        const hashedTempPassword = await hashPassword(tempPassword);

        // Atualizar senha do usuário
        await db
          .update(users)
          .set({ password: hashedTempPassword })
          .where(eq(users.id, user[0].id));

        // Registrar a alteração no log de auditoria
        await db.insert(auditLogs).values({
          user_id: user[0].id,
          action: "PASSWORD_RESET",
          details: JSON.stringify({
            method: "security-question",
            success: true
          }),
          ip_address: req.ip || "unknown",
          created_at: new Date()
        });

        // Em produção, enviaríamos a senha temporária por email
        // Por enquanto, vamos retornar na resposta (apenas para teste)
        return res.status(200).json({ 
          success: true, 
          message: "Senha temporária gerada com sucesso",
          tempPassword // REMOVER ISSO EM PRODUÇÃO
        });
      } else {
        // Método de recuperação por email

        // Gerar token de redefinição
        const resetToken = randomBytes(20).toString("hex");
        const tokenExpiry = new Date();
        tokenExpiry.setHours(tokenExpiry.getHours() + 1); // Token válido por 1 hora

        // Em um sistema real, armazenaríamos este token no banco de dados
        // e enviaríamos um email com link para redefinição

        // Registrar a tentativa no log de auditoria
        await db.insert(auditLogs).values({
          user_id: user[0].id,
          action: "PASSWORD_RESET_REQUEST",
          details: JSON.stringify({
            method: "email",
            success: true
          }),
          ip_address: req.ip || "unknown",
          created_at: new Date()
        });

        return res.status(200).json({ 
          success: true, 
          message: "Link de recuperação enviado para o email"
        });
      }
    } catch (error) {
      console.error("Erro na recuperação de senha:", error);
      res.status(500).json({ message: "Erro ao processar a recuperação de senha" });
    }
  });
}

import { Pool, neonConfig } from '@neondatabase/serverless';
import { drizzle } from 'drizzle-orm/neon-serverless';
import ws from "ws";
import * as schema from "@shared/schema";

neonConfig.webSocketConstructor = ws;

if (!process.env.DATABASE_URL) {
  throw new Error(
    "DATABASE_URL must be set. Did you forget to provision a database?",
  );
}

export const pool = new Pool({ connectionString: process.env.DATABASE_URL });
export const db = drizzle({ client: pool, schema });

import express, { type Request, Response, NextFunction } from "express";
import { registerRoutes } from "./routes";
import { setupVite, serveStatic, log } from "./vite";

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: false }));

app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on("finish", () => {
    const duration = Date.now() - start;
    if (path.startsWith("/api")) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      if (logLine.length > 80) {
        logLine = logLine.slice(0, 79) + "…";
      }

      log(logLine);
    }
  });

  next();
});

(async () => {
  const server = await registerRoutes(app);

  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    const status = err.status || err.statusCode || 500;
    const message = err.message || "Internal Server Error";

    res.status(status).json({ message });
    throw err;
  });

  // importantly only setup vite in development and after
  // setting up all the other routes so the catch-all route
  // doesn't interfere with the other routes
  if (app.get("env") === "development") {
    await setupVite(app, server);
  } else {
    serveStatic(app);
  }

  // ALWAYS serve the app on port 5000
  // this serves both the API and the client.
  // It is the only port that is not firewalled.
  const port = 5000;
  server.listen({
    port,
    host: "0.0.0.0",
    reusePort: true,
  }, () => {
    log(`serving on port ${port}`);
  });
})();

import { eq, ne, and, desc, asc, sql, count, sum, isNull, isNotNull, or, like } from "drizzle-orm";
import { db } from "./db";
import { Express, Request, Response } from "express";
import { 
  merchants, 
  users, 
  transactions,
  commissionSettings,
  auditLogs,
  transfers,
  transactionItems,
  cashbacks,
  referrals,
  qrCodes,
  settings
} from "@shared/schema";
import { isUserType } from "./routes";
import { formatCurrency } from "../client/src/lib/utils";

// Função para determinar o tipo de transferência
function getTransferType(transfer: any) {
  // Se a transferência já tem um tipo definido, retornar esse tipo
  if (transfer.type) {
    return transfer.type;
  }

  // Caso contrário, determinar o tipo com base no tipo de usuário
  if (transfer.user_type === 'merchant') {
    return 'merchant_withdrawal';
  } else if (transfer.user_type === 'client') {
    return 'client_withdrawal';
  } else {
    return 'internal_transfer';
  }
}

// Rotas administrativas
export function addAdminRoutes(app: Express) {
  // Dashboard do admin - estatísticas
  app.get("/api/admin/dashboard", isUserType("admin"), async (req, res) => {
    if (!req.user) {
      return res.status(401).json({ message: "Usuário não autenticado" });
    }

    try {
      // Contagem de usuários
      const [userCount] = await db
        .select({ count: count() })
        .from(users);

      // Contagem de lojistas
      const [merchantCount] = await db
        .select({ count: count() })
        .from(merchants);

      // Transações totais
      const [transactionCount] = await db
        .select({ count: count() })
        .from(transactions);

      // Valor total de transações - calculando do lado da aplicação 
      // já que a função SUM parece não funcionar no ambiente atual
      const allTransactions = await db
        .select({
          amount: transactions.amount
        })
        .from(transactions);

      // Calcular a soma manualmente
      const totalAmount = allTransactions.reduce((sum, tx) => {
        // Converter string para número e somar
        return sum + parseFloat(tx.amount || "0");
      }, 0);

      // Criar objeto similar ao resultado do SQL
      const transactionTotal = { total: totalAmount.toString() };

      // Transferências pendentes
      const [pendingTransfersCount] = await db
        .select({ count: count() })
        .from(transfers)
        .where(eq(transfers.status, 'pending'));

      // Último log do sistema - sem usar orderBy(desc()) que causa problemas
      const allLogs = await db
        .select()
        .from(auditLogs)
        .limit(5);

      // Ordenar manualmente e pegar o mais recente
      const lastLog = allLogs.length > 0 
        ? allLogs.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())[0]
        : undefined;

      // Lojas recentes - sem usar orderBy(desc()) que causa problemas
      const allRecentStoresResult = await db
        .select({
          id: merchants.id,
          store_name: merchants.store_name,
          created_at: merchants.created_at,
          category: merchants.category,
          owner_name: users.name
        })
        .from(merchants)
        .innerJoin(users, eq(merchants.user_id, users.id))
        .limit(10);

      // Ordenar manualmente por data de criação e pegar os 5 mais recentes
      const recentStoresResult = allRecentStoresResult
        .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())
        .slice(0, 5);

      // Formatar lojas recentes
      const recentStores = recentStoresResult.map(store => ({
        id: store.id,
        name: store.store_name,
        owner: store.owner_name,
        category: store.category || 'Geral',
        date: new Date(store.created_at).toLocaleDateString('pt-BR'),
        status: 'active'
      }));

      // Retornar todos os dados combinados
      res.json({
        userCount: userCount?.count?.toString() || "0",
        merchantCount: merchantCount?.count?.toString() || "0", 
        transactionCount: transactionCount?.count?.toString() || "0",
        transactionTotal: transactionTotal?.total?.toString() || "0",
        pendingTransfersCount: pendingTransfersCount?.count?.toString() || "0",
        recentStores: recentStores,
        lastLog: lastLog || null
      });
    } catch (error) {
      console.error("Erro ao carregar dashboard admin:", error);
      res.status(500).json({ message: "Erro ao carregar dados do dashboard" });
    }
  });

  // API para listar lojas para o painel de administração
  app.get("/api/admin/stores", isUserType("admin"), async (req, res) => {
    if (!req.user) {
      return res.status(401).json({ message: "Usuário não autenticado" });
    }
    try {
      const storesResult = await db
        .select({
          id: merchants.id,
          store_name: merchants.store_name,
          logo: merchants.logo,
          category: merchants.category,
          address: merchants.address,
          city: merchants.city,
          state: merchants.state,
          commission_rate: merchants.commission_rate,
          approved: merchants.approved,
          created_at: merchants.created_at,
          user_id: users.id,
          email: users.email,
          phone: users.phone,
          owner_name: users.name,
          type: users.type
        })
        .from(merchants)
        .innerJoin(users, eq(merchants.user_id, users.id))
        .orderBy(merchants.store_name);

      // Formatar para o frontend
      const stores = storesResult.map(store => ({
        id: store.id,
        storeId: store.id,
        userId: store.user_id,
        store_name: store.store_name,
        name: store.store_name,
        logo: store.logo || null,
        category: store.category || 'Geral',
        description: '', // Campo vazio pois não existe na tabela
        address: store.address,
        city: store.city,
        state: store.state,
        ownerName: store.owner_name,
        email: store.email,
        phone: store.phone,
        commissionRate: store.commission_rate,
        approved: store.approved,
        rating: 5.0, // Valor padrão para todas as lojas no momento
        createdAt: store.created_at
      }));

      res.json(stores);
    } catch (error) {
      console.error("Erro ao listar lojas para administração:", error);
      res.status(500).json({ message: "Erro ao listar lojas" });
    }
  });

  // Atualizar status de uma loja (ativar/desativar)
  app.patch("/api/admin/stores/:id/status", isUserType("admin"), async (req, res) => {
    if (!req.user) {
      return res.status(401).json({ message: "Usuário não autenticado" });
    }

    const storeId = parseInt(req.params.id);
    const { approved } = req.body;

    if (isNaN(storeId)) {
      return res.status(400).json({ message: "ID de loja inválido" });
    }

    try {
      // Atualizar o status de aprovação da loja
      await db
        .update(merchants)
        .set({ 
          approved: approved 
        })
        .where(eq(merchants.id, storeId));

      // Registrar no log de auditoria
      await db.insert(auditLogs).values({
        action: approved ? "store_activated" : "store_deactivated",
        details: JSON.stringify({
          storeId,
          approved
        }),
        user_id: req.user.id,
        created_at: new Date()
      });

      res.json({ 
        success: true, 
        message: approved ? "Loja ativada com sucesso" : "Loja desativada com sucesso"
      });
    } catch (error) {
      console.error("Erro ao atualizar status da loja:", error);
      res.status(500).json({ message: "Erro ao atualizar status da loja" });
    }
  });

  // Excluir uma loja
  app.delete("/api/admin/stores/:id", isUserType("admin"), async (req, res) => {
    if (!req.user) {
      return res.status(401).json({ message: "Usuário não autenticado" });
