              ELSE 'incoming'
            END as "type"
          FROM transfers t
          WHERE t.from_user_id = ${clientId} OR t.to_user_id = ${clientId}
          ORDER BY t.created_at DESC`
      );

      // Extrair IDs únicos de usuários
