import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { useLocation } from 'wouter';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';
import { saveUserData, clearUserData, getUserData } from '@/storage/local-storage';

type UserType = 'client' | 'merchant' | 'admin';

interface User {
  id: number;
  name: string;
  email: string;
  type: UserType;
  photo?: string;
  status?: string;
  invitation_code?: string;
  phone?: string;
  username?: string;
  created_at?: Date;
  last_login?: Date;
}

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string, type: UserType) => Promise<void>;
  register: (userData: any) => Promise<void>;
  logout: () => void;
  isAuthenticated: boolean;
  userType: UserType | null;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [, navigate] = useLocation();
  const { toast } = useToast();

  useEffect(() => {
    async function loadUser() {
      try {
        // Tentar carregar do localStorage primeiro
        const storedUser = getUserData();
        if (storedUser) {
          console.log('Dados encontrados no localStorage:', storedUser);
          setUser({
            id: storedUser.id,
            name: storedUser.name,
            email: storedUser.email,
            type: storedUser.type as UserType,
            photo: storedUser.photo,
            status: 'active'
          });
        }

        console.log('Carregando dados do usuário...');
        const response = await fetch('/api/auth/me', {
          credentials: 'include',
          headers: {
            'Cache-Control': 'no-cache',
            'Pragma': 'no-cache'
          }
        });

        console.log('Resposta da API:', response.status);

        if (response.ok) {
          const userData = await response.json();
          console.log('Usuário carregado:', userData);
          setUser(userData);

          // Salvar no localStorage para uso futuro
          saveUserData({
            id: userData.id,
            name: userData.name,
            email: userData.email,
            type: userData.type,
            photo: userData.photo,
            expiresAt: Date.now() + 1000 * 60 * 60 * 24 // 24 horas
          });
        } else if (response.status === 401 && user) {
          // Se recebermos 401 mas tínhamos um usuário antes, a sessão expirou
          console.log('Sessão expirada');
          clearUserData(); // Limpar localStorage
          setUser(null);
          navigate('/auth/login');
          toast({
            title: 'Sessão expirada',
            description: 'Sua sessão expirou. Por favor, faça login novamente.',
            variant: 'destructive',
          });
        } else if (response.status === 401 && !storedUser) {
          // Se recebermos 401 e não tínhamos usuário local, o usuário nunca esteve logado
          console.log('Não autenticado');

          // Verificar se estamos em uma página de convite que não requer autenticação
          const currentPath = window.location.pathname;
          const isPublicPage = 
            currentPath.startsWith('/invite') || 
            currentPath.startsWith('/convite') || 
            currentPath.startsWith('/parceiro') || 
            currentPath.startsWith('/como/te') ||
            currentPath === '/convite/cliente' ||
            currentPath === '/convite/lojista' ||
            currentPath === '/welcome' ||
            currentPath === '/welcome-static' ||
            currentPath === '/welcome-force' ||
            currentPath === '/welcome-simple' ||
            currentPath === '/'; // Todas as rotas welcome e a raiz são públicas

          // Não redirecionamos se estivermos em uma página pública
          if (!isPublicPage) {
            console.log('Não está em página pública, redirecionando para login');
            navigate('/auth/login');
          } else {
            console.log('Em página pública, ignorando redirecionamento');
          }

          setUser(null);
        }
      } catch (error) {
        console.error('Failed to load user', error);
        // Não limpar usuário em caso de erro de rede para permitir uso offline
      } finally {
        setLoading(false);
      }
    }

    // Carrega o usuário imediatamente
    loadUser();

    // E então periodicamente a cada 5 minutos (300000ms) para manter a sessão ativa
    // Aumentamos o intervalo para evitar chamadas excessivas
    const intervalId = setInterval(loadUser, 300000);

    // Limpar o intervalo quando o componente for desmontado
    return () => clearInterval(intervalId);
  }, [navigate, toast]); // Removido o 'user' das dependências para evitar atualizações excessivas

  const login = async (email: string, password: string, type: UserType) => {
    setLoading(true);
    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          email,
          password,
          type,
        }),
        credentials: 'include', // Importante para cookies de sessão
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.message || 'Falha na autenticação. Tente novamente.');
      }

      const userData = await response.json();
      setUser(userData);

      // Salvar dados no localStorage para persistência
      saveUserData({
        id: userData.id,
        name: userData.name,
        email: userData.email,
        type: userData.type,
        photo: userData.photo,
        expiresAt: Date.now() + 1000 * 60 * 60 * 24 // 24 horas
      });

      // Redirect based on user type
      if (type === 'client') {
        navigate('/client/dashboard');
      } else if (type === 'merchant') {
        navigate('/merchant/dashboard');
      } else if (type === 'admin') {
        navigate('/admin/dashboard');
      }

      toast({
        title: 'Login realizado com sucesso',
        description: `Bem-vindo(a), ${userData.name}!`,
      });
    } catch (error) {
      const err = error as Error;
      toast({
        title: 'Erro ao fazer login',
        description: err.message,
        variant: 'destructive',
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const register = async (userData: any) => {
    setLoading(true);
    try {
      const response = await fetch('/api/auth/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(userData),
        credentials: 'include',
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Erro ao cadastrar usuário');
      }

      const data = await response.json();

      toast({
        title: 'Cadastro realizado com sucesso',
        description: 'Você ganhou $10 de bônus! Já pode fazer login no sistema.',
      });

      navigate('/auth/login');
    } catch (error) {
      const err = error as Error;
      toast({
        title: 'Erro ao cadastrar',
        description: err.message,
        variant: 'destructive',
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const logout = async () => {
    try {
      await fetch('/api/auth/logout', {
        method: 'POST',
        credentials: 'include', // Importante para cookies de sessão
      });

      // Limpar o localStorage ao fazer logout
      clearUserData();

      setUser(null);
      navigate('/auth/login');

      toast({
        title: 'Logout realizado',
        description: 'Você saiu do sistema com sucesso.',
      });
    } catch (error) {
      console.error('Logout error', error);
    }
  };

  const contextValue: AuthContextType = {
    user,
    loading,
    login,
    register,
    logout,
    isAuthenticated: !!user,
    userType: user?.type || null,
  };

  return (
    <AuthContext.Provider value={contextValue}>
      {children}
    </AuthContext.Provider>
  );
}

// Objeto de cache para usuários simulados por tipo
const mockUserCache: Record<UserType, User> = {
  client: {
    id: 999,
    name: 'Cliente de Teste',
    email: 'cliente@valecashback.com',
    type: 'client',
    photo: undefined,
    status: 'active'
  },
  merchant: {
    id: 999,
    name: 'Lojista de Teste',
    email: 'lojista@valecashback.com',
    type: 'merchant',
    photo: undefined,
    status: 'active'
  },
  admin: {
    id: 999,
    name: 'Admin de Teste',
    email: 'admin@valecashback.com',
    type: 'admin',
    photo: undefined,
    status: 'active'
  }
};

// Contexto simulado memoizado para evitar re-renderizações desnecessárias
const simulatedContextCache: Partial<Record<UserType, AuthContextType>> = {};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }

  // Se estivermos em desenvolvimento e o usuário for nulo, usar um usuário simulado
  if (process.env.NODE_ENV === 'development' && !context.user) {
    const path = window.location.pathname;
    let userType: UserType | null = null;

    if (path.startsWith('/client')) {
      userType = 'client';
    } else if (path.startsWith('/merchant')) {
      userType = 'merchant';
    } else if (path.startsWith('/admin')) {
      userType = 'admin';
    }

    if (userType) {
      // Usar contexto em cache se existir, caso contrário criar um novo
      if (!simulatedContextCache[userType]) {
        console.log(`[DEV MODE] Simulando usuário tipo: ${userType}`);

        simulatedContextCache[userType] = {
          ...context,
          user: mockUserCache[userType],
          isAuthenticated: true,
          userType
        };
      }

      return simulatedContextCache[userType] as AuthContextType;
    }
  }

  return context;
};

import { createContext, ReactNode, useContext, useEffect, useState } from "react";
import { isMobileDevice } from "@/pwaHelpers";

type MobileContextType = {
  isMobile: boolean;
};

const MobileContext = createContext<MobileContextType | null>(null);

export function MobileProvider({ children }: { children: ReactNode }) {
  // Força mobile para true para este caso específico, garantindo comportamento consistente
  const [isMobile, setIsMobile] = useState<boolean>(true);

  useEffect(() => {
    // Detectar se é um dispositivo móvel na inicialização
    setIsMobile(true);

    // Também monitorar mudanças no tamanho da janela
    const handleResize = () => {
      setIsMobile(true);
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <MobileContext.Provider value={{ isMobile }}>
      {children}
    </MobileContext.Provider>
  );
}

export function useMobile() {
  const context = useContext(MobileContext);
  if (!context) {
    throw new Error("useMobile must be used within a MobileProvider");
  }
  return context.isMobile;
}

// Alias para compatibilidade
export function useIsMobile() {
  return useMobile();
}

import { useState, useCallback } from 'react';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';

interface QRCodeResponse {
  id: number;
  code: string;
  amount: number;
  expiresAt: string;
}

interface UseQRCodeProps {
  onSuccess?: (data: QRCodeResponse) => void;
  onError?: (error: Error) => void;
}

export function useQRCode({ onSuccess, onError }: UseQRCodeProps = {}) {
  const [loading, setLoading] = useState(false);
  const [qrCode, setQRCode] = useState<QRCodeResponse | null>(null);
  const { toast } = useToast();

  const generateQRCode = useCallback(async (amount: number, description?: string) => {
    setLoading(true);
    try {
      const response = await apiRequest('POST', '/api/merchant/qrcode', {
        amount,
        description,
      });

      const data = await response.json();
      setQRCode(data);
      onSuccess?.(data);
      return data;
    } catch (error) {
      const err = error as Error;
      toast({
        title: 'Erro ao gerar QR Code',
        description: err.message,
        variant: 'destructive',
      });
      onError?.(err);
    } finally {
      setLoading(false);
    }
  }, [toast, onSuccess, onError]);

  const validateQRCode = useCallback(async (code: string, payment_method = 'cashback') => {
    setLoading(true);
    try {
      const response = await apiRequest('POST', '/api/client/pay-qrcode', {
        code,
        payment_method
      });

      const data = await response.json();
      onSuccess?.(data);
      return data;
    } catch (error) {
      const err = error as Error;
      toast({
        title: 'QR Code inválido',
        description: err.message,
        variant: 'destructive',
      });
      onError?.(err);
      return null;
    } finally {
      setLoading(false);
    }
  }, [toast, onSuccess, onError]);

  // Função para processar QR code (usada pelo scanner do lojista)
  const processQrCode = useCallback(async (qrData: string) => {
    setLoading(true);
    try {
      const response = await apiRequest('POST', '/api/merchant/process-qrcode', {
        qrData
      });

      const data = await response.json();
      onSuccess?.(data);
      return data;
    } catch (error) {
      const err = error as Error;
      toast({
        title: 'Erro ao processar QR Code',
        description: err.message,
        variant: 'destructive',
      });
      onError?.(err);
      throw err; // Propagar erro para o mutation
    } finally {
      setLoading(false);
    }
  }, [toast, onSuccess, onError]);

  return {
    loading,
    qrCode,
    generateQRCode,
    validateQRCode,
    processQrCode
  };
}

import * as React from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType["ADD_TOAST"]
      toast: ToasterToast
    }
  | {
      type: ActionType["UPDATE_TOAST"]
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType["DISMISS_TOAST"]
      toastId?: ToasterToast["id"]
    }
  | {
      type: ActionType["REMOVE_TOAST"]
      toastId?: ToasterToast["id"]
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import translations, { LanguageCode, languages } from '@/i18n';

type Path<T> = T extends object ? {
  [K in keyof T]: `${K & string}${Path<T[K]> extends never ? '' : `.${Path<T[K]>}`}`;
}[keyof T] : never;

type TranslationPath = Path<typeof translations.pt>;

interface TranslationContextType {
  language: LanguageCode;
  setLanguage: (lang: LanguageCode) => void;
  t: (key: string, params?: Record<string, string | number>) => string;
  languages: typeof languages;
}

const defaultLanguage: LanguageCode = 'pt';

const TranslationContext = createContext<TranslationContextType | undefined>(undefined);

const getNestedValue = (obj: any, path: string) => {
  return path.split('.').reduce((prev, curr) => {
    return prev && prev[curr] !== undefined ? prev[curr] : undefined;
  }, obj);
};

const replaceParams = (text: string, params?: Record<string, string | number>) => {
  if (!params) return text;

  let result = text;
  Object.entries(params).forEach(([key, value]) => {
    result = result.replace(new RegExp(`{{${key}}}`, 'g'), String(value));
  });

  return result;
};

export const TranslationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [language, setLanguageState] = useState<LanguageCode>(() => {
    // Tenta recuperar o idioma salvo do localStorage
    const savedLanguage = localStorage.getItem('language') as LanguageCode;
    return savedLanguage && Object.keys(translations).includes(savedLanguage) 
      ? savedLanguage 
      : defaultLanguage;
  });

  useEffect(() => {
    // Salva a preferência de idioma no localStorage
    localStorage.setItem('language', language);
    // Atualiza o atributo lang da página para acessibilidade
    document.documentElement.lang = language;
    // Força uma atualização de renderização quando o idioma muda
    window.dispatchEvent(new Event('language-changed'));
  }, [language]);

  const setLanguage = (lang: LanguageCode) => {
    if (translations[lang]) {
      setLanguageState(lang);
    }
  };

  const t = (key: string, params?: Record<string, string | number>): string => {
    const translatedValue = getNestedValue(translations[language], key);

    if (translatedValue === undefined) {
      console.warn(`Translation key not found: ${key}`);
      return key;
    }

    if (typeof translatedValue === 'string') {
      return replaceParams(translatedValue, params);
    }

    return key;
  };

  return (
    <TranslationContext.Provider value={{ language, setLanguage, t, languages }}>
      {children}
    </TranslationContext.Provider>
  );
};

export const useTranslation = () => {
  const context = useContext(TranslationContext);
  if (context === undefined) {
    throw new Error('useTranslation must be used within a TranslationProvider');
  }
  return context;
};

