import React from 'react';
import { useAuth } from '@/hooks/use-auth';
import { Route, Redirect } from 'wouter';
import { Loader2 } from 'lucide-react';
import { MobileLayout } from '@/components/ui/mobile-layout';

interface ProtectedRouteMobileProps {
  path: string;
  component: React.ComponentType<any>;
  userType?: string;
  title: string;
}

export function ProtectedRouteMobile({
  path,
  component: Component,
  userType,
  title,
}: ProtectedRouteMobileProps) {
  const { user, loading } = useAuth();

  // Se a autenticação estiver em andamento, mostrar carregamento
  if (loading) {
    return (
      <Route path={path}>
        <div className="flex items-center justify-center min-h-screen">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
      </Route>
    );
  }

  // Se não estiver autenticado, redirecionar para login
  if (!user) {
    return (
      <Route path={path}>
        <Redirect to="/auth/login" />
      </Route>
    );
  }

  // Se userType for especificado e não corresponder ao tipo do usuário
  if (userType && user.type !== userType) {
    // Redirecionar para o dashboard apropriado
    const redirectPath = `/${user.type}/dashboard`;
    return (
      <Route path={path}>
        <Redirect to={redirectPath} />
      </Route>
    );
  }

  // Usar sempre o layout móvel para esta rota
  return (
    <Route path={path}>
      <MobileLayout title={title}>
        <Component />
      </MobileLayout>
    </Route>
  );
}

import { useAuth } from "@/hooks/use-auth";
import { Loader2 } from "lucide-react";
import { Redirect, Route, RouteComponentProps } from "wouter";

interface ProtectedRouteProps {
  path: string;
  component: React.ComponentType<RouteComponentProps>;
  userType?: "client" | "merchant" | "admin" | null;
}

export function ProtectedRoute({
  path,
  component: Component,
  userType,
}: ProtectedRouteProps) {
  const { user, loading, userType: currentUserType } = useAuth();

  return (
    <Route
      path={path}
      component={(props) => {
        if (loading) {
          return (
            <div className="flex items-center justify-center min-h-screen">
              <Loader2 className="h-8 w-8 animate-spin text-primary" />
            </div>
          );
        }

        if (!user) {
          return <Redirect to="/auth/login" />;
        }

        // Não redirecionar a rota raiz - deixar que o componente welcome-simple seja mostrado
        // A página de boas-vindas agora é renderizada diretamente no Router do App.tsx

        // Se um tipo específico de usuário for requerido para esta rota
        if (userType && currentUserType !== userType) {
          // Redirecionar para o dashboard apropriado
          if (currentUserType === "client") {
            return <Redirect to="/client/dashboard" />;
          } else if (currentUserType === "merchant") {
            return <Redirect to="/merchant/dashboard" />;
          } else if (currentUserType === "admin") {
            return <Redirect to="/admin/dashboard" />;
          }

          // Fallback
          return <Redirect to="/auth/login" />;
        }

        return <Component {...props} />;
      }}
    />
  );
}

