/* Estilos para o prompt de instalação de PWA */

.pwa-install-banner {
  opacity: 0;
  transform: translateY(20px);
  animation: slide-up 0.4s ease forwards;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
  transition: all 0.3s ease;
}

.pwa-install-banner:hover {
  transform: translateY(-2px);
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
}

@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.pwa-icon-pulse {
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.05);
  }
  100% {
    transform: scale(1);
  }
}

.pwa-install-btn {
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
}

.pwa-install-btn:hover {
  transform: translateY(-2px);
}

.pwa-install-btn::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 150%;
  height: 150%;
  background-color: rgba(255, 255, 255, 0.1);
  border-radius: inherit;
  transform: translate(-50%, -50%) scale(0);
  opacity: 0;
  transition: transform 0.3s, opacity 0.3s;
}

.pwa-install-btn:hover::after {
  transform: translate(-50%, -50%) scale(1);
  opacity: 1;
}

.pwa-instructions-step {
  transition: all 0.3s ease;
}

.pwa-instructions-step:hover {
  background-color: rgba(0, 0, 0, 0.02);
}

.pwa-qr-code-container {
  position: relative;
  overflow: hidden;
  border-radius: 8px;
}

.pwa-qr-code-container::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: linear-gradient(
    to bottom right,
    rgba(255, 255, 255, 0) 0%,
    rgba(255, 255, 255, 0.3) 50%,
    rgba(255, 255, 255, 0) 100%
  );
  transform: rotate(30deg);
  animation: qr-shine 3s infinite;
}

@keyframes qr-shine {
  from {
    transform: translateX(-100%) rotate(30deg);
  }
  to {
    transform: translateX(100%) rotate(30deg);
  }
}

.pwa-screenshot {
  transition: transform 0.3s ease;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.pwa-screenshot:hover {
  transform: scale(1.03);
}

.pwa-tab-active {
  position: relative;
}

.pwa-tab-active::after {
  content: '';
  position: absolute;
  bottom: -8px;
  left: 0;
  width: 100%;
  height: 2px;
  background-color: currentColor;
  animation: tab-indicator 0.3s ease forwards;
}

@keyframes tab-indicator {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

.pwa-close-btn {
  transition: all 0.2s ease;
  opacity: 0.7;
}

.pwa-close-btn:hover {
  opacity: 1;
  transform: rotate(90deg);
}

.pwa-install-progress {
  overflow: hidden;
  position: relative;
  height: 4px;
  width: 100%;
  border-radius: 2px;
  background-color: rgba(0, 0, 0, 0.1);
}

.pwa-install-progress::after {
  content: '';
  position: absolute;
  height: 100%;
  width: 30%;
  background-color: currentColor;
  animation: progress-bar 1.5s ease infinite;
  border-radius: 2px;
}

@keyframes progress-bar {
  0% {
    left: -30%;
  }
  100% {
    left: 100%;
  }
}

/* Estilos específicos para dispositivos */
.ios-steps li {
  position: relative;
  padding-left: 24px;
}

.ios-steps li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 8px;
  width: 16px;
  height: 16px;
  background-color: currentColor;
  border-radius: 50%;
  opacity: 0.2;
}

.android-steps li {
  position: relative;
  padding-left: 24px;
}

.android-steps li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 8px;
  width: 16px;
  height: 16px;
  background-color: currentColor;
  border-radius: 4px;
  opacity: 0.2;
}

/* Estilos de transição de página */
.pwa-page-transition {
  opacity: 0;
  transform: translateY(10px);
  animation: fade-in 0.3s ease forwards;
}

@keyframes fade-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

