            className={language === lang.code ? "bg-primary/10 font-bold" : ""}
          >
            <span className="text-xl mr-2">{flagEmojis[lang.code]}</span>
            <span className="font-medium">{lang.name}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

