                    </Button>
                  </CardFooter>
                </Card>
              </TabsContent>

              {/* Imagens (logo, favicon, etc.) */}
              <TabsContent value="images">
                <div className="grid gap-6 md:grid-cols-2">
                  {/* Logo */}
                  <Card>
                    <CardHeader>
                      <CardTitle>Logo</CardTitle>
