import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { MainLayout } from "@/components/layout/main-layout";
import { 
  Users, 
  Store, 
  DollarSign, 
  TrendingUp, 
  AlertTriangle,
  CheckCircle,
  Clock,
  BarChart3,
  Shield,
  Settings,
  FileText,
  Wallet,
  Activity,
  Eye,
  UserCheck,
  UserX,
  Search
} from "lucide-react";
import { Link } from "wouter";
import { motion } from "framer-motion";
import { useState } from "react";

interface AdminStats {
  totalUsers: number;
  totalMerchants: number;
  pendingApprovals: number;
  totalTransactions: number;
  totalVolume: number;
  monthlyGrowth: number;
  activeSessions: number;
  pendingWithdrawals: number;
}

interface RecentActivity {
  id: number;
  type: string;
  user: string;
  action: string;
  amount?: number;
  timestamp: string;
  status: string;
}

interface UserSummary {
  id: number;
  name: string;
  email: string;
  type: string;
  status: string;
  balance: number;
  lastActivity: string;
}

interface PendingApproval {
  id: number;
  merchantName: string;
  businessName: string;
  email: string;
  submittedAt: string;
  documents: string[];
}

export default function CompleteAdminPanel() {
  const [searchTerm, setSearchTerm] = useState("");

  const { data: adminStats } = useQuery<AdminStats>({
    queryKey: ['/api/admin/stats']
  });

  const { data: recentActivity } = useQuery<RecentActivity[]>({
    queryKey: ['/api/admin/recent-activity']
  });

  const { data: userSummary } = useQuery<UserSummary[]>({
    queryKey: ['/api/admin/users-summary']
  });

  const { data: pendingApprovals } = useQuery<PendingApproval[]>({
    queryKey: ['/api/admin/pending-approvals']
  });

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(value);
  };

  const getActivityIcon = (type: string) => {
    switch (type) {
      case 'transaction':
        return <DollarSign className="h-4 w-4 text-green-600" />;
      case 'withdrawal':
        return <Wallet className="h-4 w-4 text-blue-600" />;
      case 'user_registration':
        return <Users className="h-4 w-4 text-purple-600" />;
      case 'merchant_approval':
        return <Store className="h-4 w-4 text-orange-600" />;
      default:
        return <Activity className="h-4 w-4 text-gray-600" />;
    }
  };

  const getStatusBadge = (status: string) => {
    const statusConfig = {
      active: { color: 'bg-green-100 text-green-700', label: 'Ativo' },
      pending: { color: 'bg-yellow-100 text-yellow-700', label: 'Pendente' },
      suspended: { color: 'bg-red-100 text-red-700', label: 'Suspenso' },
      completed: { color: 'bg-green-100 text-green-700', label: 'Concluído' },
      processing: { color: 'bg-blue-100 text-blue-700', label: 'Processando' }
    };

    const config = statusConfig[status as keyof typeof statusConfig] || statusConfig.pending;

    return (
      <Badge className={config.color}>
        {config.label}
      </Badge>
    );
  };

  const actions = (
    <div className="flex gap-2">
      <Link href="/admin/users">
        <Button variant="outline" className="gap-2">
          <Users className="h-4 w-4" />
          Gerenciar Usuários
        </Button>
      </Link>
      <Link href="/admin/reports">
        <Button className="gap-2 bg-[#3db54e] hover:bg-[#36a146]">
