                        {selectedUser.country && (
                          <div className="flex items-center text-sm">
                            <Globe className="h-4 w-4 mr-2 text-primary" />
                            <span>
                              {selectedUser.country}
                              {selectedUser.country_code && ` (${selectedUser.country_code})`}
                            </span>
                          </div>
