export default function AdminStores() {
  const [selectedStore, setSelectedStore] = useState<any | null>(null);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isBlockDialogOpen, setIsBlockDialogOpen] = useState(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [isCommissionDialogOpen, setIsCommissionDialogOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [commissionRate, setCommissionRate] = useState<string>("2.0");
  const [storesToDelete, setStoresToDelete] = useState<any[]>([]);
  const { toast } = useToast();

  // Query to get stores data
  const { data, isLoading } = useQuery({
    queryKey: ['/api/admin/stores'],
    queryFn: getQueryFn({ on401: "throw" }),
  });

  // Usa os dados da API ou um array vazio enquanto carrega
  const storesData = Array.isArray(data) ? data : [];

  const handleViewStore = (store: any) => {
    setSelectedStore(store);
    setIsDialogOpen(true);
  };

  const handleEditStore = (store: any) => {
    // This would navigate to an edit form in a real implementation
    toast({
      title: "Editar loja",
      description: `Editando ${store.name}`,
    });
  };

  // Lojas agora são aprovadas automaticamente, não é mais necessário os diálogos de aprovação e rejeição

  const handleBlockDialog = (store: any) => {
    setSelectedStore(store);
    setIsBlockDialogOpen(true);
  };

  const handleCommissionDialog = (store: any) => {
    setSelectedStore(store);
    setCommissionRate(store.commissionRate?.toString() || "2.0");
    setIsCommissionDialogOpen(true);
  };

  // Funções de aprovação e rejeição removidas, pois lojas são aprovadas automaticamente

  const handleBlockStore = async () => {
    if (!selectedStore) return;

    setIsProcessing(true);

    try {
      // API call para atualizar o status da loja
      const newApprovedStatus = !selectedStore.approved;
      const response = await apiRequest("PATCH", `/api/admin/stores/${selectedStore.id}/status`, {
        approved: newApprovedStatus
      });

      if (response.ok) {
        const action = newApprovedStatus ? "ativada" : "desativada";

        toast({
          title: `Loja ${action}`,
          description: `${selectedStore.name || selectedStore.store_name} foi ${action} com sucesso.`,
        });

        queryClient.invalidateQueries({ queryKey: ['/api/admin/stores'] });
        setIsBlockDialogOpen(false);
      } else {
        throw new Error("Erro ao alterar status da loja");
      }
    } catch (error) {
      console.error("Erro ao alterar status:", error);
      toast({
        title: "Erro",
        description: "Ocorreu um erro ao alterar o status da loja.",
        variant: "destructive",
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleUpdateCommission = async () => {
    if (!selectedStore) return;

    setIsProcessing(true);

    try {
      // This would be an API call in a real implementation
      await new Promise(resolve => setTimeout(resolve, 1000));

      toast({
        title: "Comissão atualizada",
        description: `Taxa de comissão para ${selectedStore.name} alterada para ${commissionRate}%.`,
      });

      queryClient.invalidateQueries({ queryKey: ['/api/admin/stores'] });
      setIsCommissionDialogOpen(false);
    } catch (error) {
      toast({
        title: "Erro",
        description: "Ocorreu um erro ao atualizar a taxa de comissão.",
        variant: "destructive",
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case "active": return "Ativa";
      case "inactive": return "Inativa";
      case "pending": return "Pendente";
      default: return status;
    }
  };

  const getInitials = (name: string = "") => {
    return name
      .split(' ')
      .map(n => n[0])
      .slice(0, 2)
      .join('')
      .toUpperCase();
  };

  // Column configuration
  const columns = [
    {
      header: "ID",
      accessorKey: "id",
    },
    {
      header: "Nome",
      accessorKey: "store_name",
      cell: ({ row }: any) => {
        const value = row.original.store_name || row.original.name || "";
        return <span>{value}</span>;
      },
    },
    {
      header: "Responsável",
      accessorKey: "ownerName",
      cell: ({ row }: any) => {
        const value = row.original.ownerName || "";
        return <span>{value}</span>;
      },
    },
    {
      header: "Categoria",
      accessorKey: "category",
      cell: ({ row }: any) => {
        const value = row.original.category || "Geral";
        return <span>{value}</span>;
      },
    },
    {
      header: "Status",
      accessorKey: "approved",
      cell: ({ row }: any) => {
        // Utiliza approved como indicador de status já que não há campo status
        const approved = row.original.approved;
        const status = approved === false ? "inactive" : "active";
        return (
          <Badge 
            variant="outline"
            className={
