    const emailsToDelete = ["alexmoura-2025@hotmail.com", "lojista@valecashback.com"];

    if (data && Array.isArray(data)) {
      const foundStores = data.filter(store => 
        emailsToDelete.includes(store.email)
      );

      if (foundStores.length > 0) {
