  ];

  // Se o usuário não for do tipo cliente, exiba uma mensagem de erro
  if (user?.type !== "client") {
    return (
      <DashboardLayout title={t('navigation.referrals')} type="client">
        <Card className="border-destructive">
          <CardHeader>
            <CardTitle className="text-destructive">{t('common.restrictedAccess')}</CardTitle>
            <CardDescription>
              {t('referrals.clientOnly')}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p>{t('referrals.permissionDenied')}</p>
          </CardContent>
        </Card>
      </DashboardLayout>
    );
  }

  // Se houver um erro na busca, exiba uma mensagem para o usuário
  if (referralsError) {
    return (
      <DashboardLayout title={t('navigation.referrals')} type="client">
        <Card className="border-destructive">
          <CardHeader>
            <CardTitle className="text-destructive">{t('common.loadingError')}</CardTitle>
            <CardDescription>
              {t('referrals.loadingError')}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p>{t('common.reloadMessage')}</p>
            <Button 
              onClick={() => window.location.reload()} 
              className="mt-4"
            >
              <RefreshCw className="h-4 w-4 mr-2" />
              {t('common.reloadPage')}
            </Button>
          </CardContent>
        </Card>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout title={t('navigation.referrals')} type="client">
      <div className="flex flex-col space-y-4">
        <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-4">
          <TabsList>
            <TabsTrigger value="overview">
              <Users className="h-4 w-4 mr-2" />
