            </TabsTrigger>
            <TabsTrigger value="list">
              <Percent className="h-4 w-4 mr-2" />
              {t('referrals.myReferrals')}
            </TabsTrigger>
          </TabsList>

          {/* Aba de Visão Geral */}
          <TabsContent value="overview">
            <div className="grid md:grid-cols-2 gap-6">
              <motion.div
                initial={{ opacity: 0, y: 20 }}
