                        </Button>
                      </motion.div>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            </div>
          </TabsContent>

          {/* Aba de Indicados */}
          <TabsContent value="list">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
