            <Link href="/merchant/reports">
              <Button variant="outline" className="w-full h-auto p-4 flex flex-col items-center gap-2">
                <Eye className="h-6 w-6" />
                <span>Relatórios</span>
              </Button>
            </Link>
          </div>
        </CardContent>
      </Card>
    </DashboardLayout>
  );
}

