                  </span>
                </CardFooter>
              )}
            </Card>
          </TabsContent>

          {/* Segurança e Senha */}
          <TabsContent value="security" className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Alterar Senha</CardTitle>
                <CardDescription>Altere sua senha de acesso ao sistema</CardDescription>
              </CardHeader>
