          ) : (
            <span className="text-muted-foreground text-xs">N/A</span>
          )}
        </div>
      )
    },
    { header: "Data", accessorKey: "date" },
    { 
      header: "Status", 
      accessorKey: "status",
      cell: (row: any) => (
        <div className="flex items-center">
          <span className={`px-2 py-1 rounded-full text-xs font-medium ${
