                  {(() => {
                    const change = parseFloat(String(reportsData.salesData.previousPeriodChange));
                    if (isNaN(change)) return <span>0%</span>;

                    return change >= 0 ? (
                      <>
                        <ArrowUpRight className="h-4 w-4 text-green-500 mr-1" />
