    if (!replyMessage.trim() || !selectedTicket) return;

    if (selectedTicket.status === "closed") {
      toast({
        title: "Ticket encerrado",
        description: "Este ticket está encerrado. Por favor, abra um novo ticket para continuar a conversa.",
